{
  "aggregate_id": "DEF-NRS-484A-130::motor_vehicle",
  "classifications": [
    {
      "class": "ru.bicycle",
      "verdict": "supported",
      "reason": "The contract describes a human-powered device, which the vehicle definition expressly excepts."
    },
    {
      "class": "ru.bus",
      "verdict": "supported",
      "reason": "The bus contract describes a motor vehicle carrying passengers, matching the controlling admitting clause."
    },
    {
      "class": "ru.child",
      "verdict": "supported",
      "reason": "The contract describes a pedestrian person rather than a transport device, so the admitting words do not reach it."
    },
    {
      "class": "ru.commercial_motor_vehicle",
      "verdict": "supported",
      "reason": "Every member admitted as self-propelled and non-rail, after the named exclusions, satisfies at least one of the three quoted covering contracts."
    },
    {
      "class": "ru.electric_bicycle",
      "verdict": "supported",
      "reason": "The controlling definition expressly excludes electric bicycles."
    },
    {
      "class": "ru.electric_scooter",
      "verdict": "supported",
      "reason": "The controlling definition expressly excludes electric scooters."
    },
    {
      "class": "ru.emergency_vehicle",
      "verdict": "supported",
      "reason": "Emergency designation alone does not establish propulsion, but every admitted member satisfies one of the three quoted covering contracts."
    },
    {
      "class": "ru.fire_apparatus",
      "verdict": "underdetermined",
      "reason": "The firefighting-vehicle contract permits separately classified powered two-wheelers, which the full ru.motor_vehicle contract excludes despite the omission of that limitation from the quoted basis."
    },
    {
      "class": "ru.moped",
      "verdict": "supported",
      "reason": "The moped definition supplies engine propulsion and expressly distinguishes mopeds from the electric bicycles and scooters excluded by the controlling definition."
    },
    {
      "class": "ru.motor_vehicle",
      "verdict": "supported",
      "reason": "Its contract supplies self-propulsion and non-rail operation while separating the jurisdiction's separately classified powered two-wheelers."
    },
    {
      "class": "ru.motorcycle",
      "verdict": "supported",
      "reason": "The contract describes a motor vehicle with additional wheel and riding-position characteristics that do not defeat the admitting clause."
    },
    {
      "class": "ru.official_vehicle",
      "verdict": "supported",
      "reason": "Official service alone does not establish propulsion, but every admitted member falls within at least one of the three quoted covering contracts."
    },
    {
      "class": "ru.pedestrian",
      "verdict": "supported",
      "reason": "The contract identifies a person rather than a transport device, and the vehicle definition additionally excepts electric personal assistive mobility devices."
    },
    {
      "class": "ru.pedestrian_with_white_cane_or_guide_animal",
      "verdict": "supported",
      "reason": "The contract still identifies a pedestrian person rather than a device admitted by the vehicle definition."
    },
    {
      "class": "ru.rail_vehicle",
      "verdict": "supported",
      "reason": "The on-track equipment described by the contract fails the controlling requirement that a motor vehicle not be operated upon rails."
    },
    {
      "class": "ru.school_bus",
      "verdict": "supported",
      "reason": "The contract describes a bus with a school designation, retaining the motor-vehicle character reached by the admitting clause."
    },
    {
      "class": "ru.taxicab",
      "verdict": "underdetermined",
      "reason": "Passenger hire and identifying markings do not preclude separately classified powered two-wheelers, which the sole covering class expressly omits."
    },
    {
      "class": "ru.tour_bus_or_limousine",
      "verdict": "underdetermined",
      "reason": "The lengthened passenger-vehicle alternative does not preclude separately classified powered two-wheelers, so the truncated ru.motor_vehicle basis does not establish complete coverage."
    },
    {
      "class": "ru.trailer_or_combination",
      "verdict": "contradicted",
      "reason": "Any combination admitted as a self-propelled non-rail vehicle necessarily satisfies at least one of the already-proposed included contracts, so uncertainty about other combinations does not establish irresolution."
    },
    {
      "class": "ru.transit_bus",
      "verdict": "supported",
      "reason": "The public-transit qualification leaves the class a bus whose motor-vehicle contract meets the admitting words."
    },
    {
      "class": "ru.truck",
      "verdict": "supported",
      "reason": "The truck contract expressly describes a motor vehicle, with its goods-carrying purpose adding no conflicting limitation."
    }
  ]
}

